command:
cd /code && jupyter nbconvert --to notebook --execute FGBR_OC.ipynb --output FGBR_OC_executed.ipynb --output-dir /results --ExecutePreprocessor.timeout=-1 --ExecutePreprocessor.allow_errors=True >/tmp/nb.log 2>&1 && tail -20 /tmp/nb.log && python - <<'PY'
import nbformat
nb=nbformat.read('/results/FGBR_OC_executed.ipynb', as_version=4)
for i,cell in enumerate(nb.cells):
    if cell.cell_type=='code' and cell.outputs:
        print('\nCELL',i)
        for out in cell.outputs:
            if out.output_type=='stream':
                print(out.text)
PY
